static int run(const char *label, int isb, int par, int keyed, const char *const *kat) {
    u8 key[64], msg[256], got[64], want[64]; int ol = isb ? 64 : 32, good = 0;
    for (int i = 0; i < 64; i++) key[i] = (u8)i;
    for (int i = 0; i < 256; i++) msg[i] = (u8)i;
    u32 keylen = keyed ? (u32)ol : 0;
    for (int n = 0; n < 256; n++) {
        for (int i = 0; i < ol; i++) want[i] = (u8)(hexval(kat[n][2 * i]) * 16 + hexval(kat[n][2 * i + 1]));
        if (par) blake2_par(isb, key, keylen, msg, (u32)n, got); else blake2_seq(isb, key, keylen, msg, (u32)n, got);
        int ok = 1; for (int i = 0; i < ol; i++) if (got[i] != want[i]) ok = 0;
        good += ok;
        if (!ok) { pstr("FAIL "); pstr(label); pstr(keyed ? " keyed" : " unkeyed"); pstr(" length "); pdec(n); pstr(": "); phex_bytes(got, ol); pstr("\n"); }
    }
    pstr(label); pstr(keyed ? " keyed: " : " unkeyed: "); pdec(good); pstr(" of 256 match\n");
    return good;
}
int paper_main(void) {
    int good = 0;
    good += run("BLAKE2b", 1, 0, 0, KAT_BLAKE2B_PLAIN); good += run("BLAKE2b", 1, 0, 1, KAT_BLAKE2B_KEYED);
    good += run("BLAKE2s", 0, 0, 0, KAT_BLAKE2S_PLAIN); good += run("BLAKE2s", 0, 0, 1, KAT_BLAKE2S_KEYED);
    good += run("BLAKE2bp", 1, 1, 0, KAT_BLAKE2BP_PLAIN); good += run("BLAKE2bp", 1, 1, 1, KAT_BLAKE2BP_KEYED);
    good += run("BLAKE2sp", 0, 1, 0, KAT_BLAKE2SP_PLAIN); good += run("BLAKE2sp", 0, 1, 1, KAT_BLAKE2SP_KEYED);
    pstr("total: "); pdec(good); pstr(" of 2048 match\n");
    pstr(good == 2048 ? "PASS\n" : "FAIL\n");
    return good == 2048 ? 0 : 1;
}
